144	  public static <E extends Enum<E>> ImmutableSet<E> immutableEnumSet(Iterable<E> elements) {
145	    if (elements instanceof ImmutableEnumSet) {
146	      return (ImmutableEnumSet<E>) elements;
147	    } else if (elements instanceof Collection) {
148	      Collection<E> collection = (Collection<E>) elements;
149	      if (collection.isEmpty()) {
150	        return ImmutableSet.of();
151	      } else {
152	        return ImmutableEnumSet.asImmutable(EnumSet.copyOf(collection));
153	      }
154	    } else {
155	      Iterator<E> itr = elements.iterator();
156	      if (itr.hasNext()) {
157	        EnumSet<E> enumSet = EnumSet.of(itr.next());
158	        addAll(enumSet, itr);
159	        return ImmutableEnumSet.asImmutable(enumSet);
160	      } else {
161	        return ImmutableSet.of();
162	      }
163	    }
164	  }
